  function renderOptions(target,text){
    optionItems=actions.parse(text);
    if(!optionItems.length){renderText(target,text);const note=document.querySelector('[data-wave-action-feedback]');note.textContent='选项编号尚不完整；可先阅读原文，完整的 1—5 条选项才会启用点击。';note.setAttribute('data-error','');return;}
    target.replaceChildren();
    const list=document.createElement('ol');list.setAttribute('data-wave-choices','');
    for(const [index,item] of optionItems.entries()){
      const li=document.createElement('li'),button=document.createElement('button');
      button.type='button';button.setAttribute('data-wave-choice',String(index));
      if(item.unavailable)button.setAttribute('data-wave-unavailable','');
      const number=document.createElement('span');number.setAttribute('data-wave-choice-number','');number.textContent=String(item.number);
      const copy=document.createElement('span'),category=document.createElement('span');category.setAttribute('data-wave-choice-category','');category.textContent=item.category;
      copy.append(category,document.createTextNode(item.action));button.append(number,copy);li.append(button);list.append(li);
    }
    target.append(list);updateActions(actions.getState());
  }
  function dispose() {disposed=true;if(timer!==null)clearTimeout(timer);timer=null;actions?.dispose();}
  async function refresh() {
    if (disposed) return;
    const panel=document.querySelector('[data-wave-ui]'), copy=document.querySelector('[data-wave-copy]'), phase=document.querySelector('[data-wave-phase]');
    let busy=false;
    try {
      if (typeof getCurrentMessageId!=='function' || typeof getChatMessages!=='function') throw new Error('无法读取本楼消息：请确认正在使用酒馆助手的楼层前端，并启用了渲染器。兼容客户端还需提供本楼消息读取接口。');
      const id=getCurrentMessageId();
      const rows=await getChatMessages(id);
      const row=rows.find(item=>item.message_id===id);
      if (!row || typeof row.message!=='string') throw new Error('本楼消息暂未保存或尚未就绪；请等回复结束，再刷新本楼。');
      const blocks=extract(row.message,config.kind);
      if (!blocks.length) throw new Error('本楼缺少完整的对应条目，或其它正则改变了来源标签；请检查消息原文。');
      const block=blocks[occurrence(blocks.length)];
      if (!block) throw new Error('没有找到与这个面板对应的内容；请刷新本楼。');
      busy=config.kind==='plan' && block.state==='';
      panel.setAttribute('data-wave-state',block.state);
      if (phase) {phase.textContent=busy?'正在构思':'规划完成';phase.toggleAttribute('data-wave-busy',busy);phase.toggleAttribute('data-wave-done',!busy);}
      const key=block.text+'\u0000'+block.state;
      if (last!==key) {
        if(config.kind==='options'&&actions)renderOptions(copy,block.text);
        else if(config.kind==='mind'){
          const name=/^\s*\*\*([^*\n]{1,24})\*\*\s*(?:\r?\n|$)/.exec(block.text);
          document.querySelector('[data-wave-title]').textContent=name?name[1]+' · 心声':'人物心声';
