    } catch (error) {
      panel.setAttribute('data-wave-error','');
      copy.textContent=error instanceof Error?error.message:String(error);
      panel.open=true;
      if (phase) phase.textContent='读取未完成';
      failures++;
    }
    // Only incomplete planning or a bounded initial retry needs a timer.
    if (!disposed && (busy || failures>0 && failures<4)) timer=setTimeout(refresh,700);
  }
  function start() {
    window.addEventListener('pagehide',dispose,{once:true});
    window.addEventListener('unload',dispose,{once:true});
    if(config.kind==='options'&&typeof createWaveActionController==='function'){
      actions=createWaveActionController(window);actions.subscribe(updateActions);
