    return parsed.some(item=>!item.action)?[]:parsed;
  }
  function getHost(){
    try{
      const doc=runtime.parent?.document ?? runtime.document;
      if(!doc?.body)throw new Error();
      const input=doc.querySelector('#send_textarea');
      if(!input||typeof input.value!=='string')throw new Error();
      hostWindow=doc.defaultView;
      return {doc,input,win:doc.defaultView};
    }catch{throw new Error('找不到酒馆输入框；请确认已打开 SillyTavern 或 TauriTavern 的聊天输入区，并刷新本楼重试。');}
  }
  function getState(){return {mode,pending,submitted,feedback,error};}
  function announce(text,isError=false){feedback=text;error=isError;if(!disposed)listener(getState());}
  function loadMode(){try{mode=runtime.localStorage?.getItem(storageKey)==='send'?'send':'draft';}catch{mode='draft';}}
  function setMode(value){mode=value==='send'?'send':'draft';try{runtime.localStorage?.setItem(storageKey,mode);}catch{}if(!disposed)listener(getState());}
  function storageChanged(event){if(event.key===storageKey){loadMode();if(!disposed)listener(getState());}}
  function writeInput(host,value){host.input.value=value;host.input.dispatchEvent(new host.win.Event('input',{bubbles:true}));}
  function payload(action){
    // Do not add a sentence prefix. Fullwidth braces keep a model-supplied
    // macro from being interpreted by substituteParams.
